t week","Flexible"]}]},{"label":"Music lessons","slug":"lessons-coaching-music-lessons","sort_order":2,"is_root":false,"questions":[{"label":"Instrument","options":["Piano","Guitar","Voice","Drums","Other"]},{"label":"When do you need it?","options":["As soon as possible","This week","Next week","Flexible"]}]},{"label":"Language lessons","slug":"lessons-coaching-language-lessons","sort_order":3,"is_root":false,"questions":[{"label":"Language","options":["English","Spanish","French","Other"]},{"label":"When do you need it?","options":["As soon as possible","This week","Next week","Flexible"]}]},{"label":"Fitness coaching","slug":"lessons-coaching-fitness-coaching","sort_order":4,"is_root":false,"questions":[{"label":"Training goal","options":["Strength","General fitness","Mobility","Sport-specific"]},{"label":"When do you need it?","options":["As soon as possible","This week","Next week","Flexible"]}]}]},{"label":"Pet care","slug":"pet-care","scope":"service","sort_order":100,"legacy_label":"Pet care","children":[{"label":"Dog walking","slug":"pet-care-dog-walking","sort_order":1,"is_root":false,"questions":[{"label":"Walk duration","options":["15 minutes","30 minutes","60 minutes"]},{"label":"When do you need it?","options":["As soon as possible","This week","Next week","Flexible"]}]},{"label":"Pet sitting","slug":"pet-care-pet-sitting","sort_order":2,"is_root":false,"questions":[{"label":"Care arrangement","options":["Drop-in visits","Overnight care","Boarding","Flexible"]},{"label":"When do you need it?","options":["As soon as possible","This week","Next week","Flexible"]}]},{"label":"Grooming","slug":"pet-care-grooming","sort_order":3,"is_root":false,"questions":[{"label":"Grooming service","options":["Bath","Haircut","Nail trim","Full grooming"]},{"label":"When do you need it?","options":["As soon as possible","This week","Next week","Flexible"]}]},{"label":"Pet training","slug":"pet-care-pet-training","sort_order":4,"is_root":false,"questions":[{"label":"Training goal","options":["Basic obedience","Puppy training","Leash skills","Behavior support"]},{"label":"When do you need it?","options":["As soon as possible","This week","Next week","Flexible"]}]}]},{"label":"Other service","slug":"other-service","scope":"service","sort_order":110,"legacy_label":"Other service","children":[{"label":"Other service","slug":"other-service","sort_order":1,"is_root":true,"questions":[{"label":"How often do you need it?","options":["One time","Recurring","Still deciding"]},{"label":"When do you need it?","options":["As soon as possible","This week","Next week","Flexible"]}]}]}]$data$::jsonb;
  root jsonb; leaf jsonb; question jsonb; choice jsonb;
  v_parent_id uuid; v_category_id uuid; v_group_id uuid; question_order integer; choice_order integer;
BEGIN
  FOR root IN SELECT value FROM jsonb_array_elements(roots) LOOP
    INSERT INTO hocalist.catalogue_categories(label,slug,scope,sort_order)
    VALUES(root->>'label',root->>'slug',root->>'scope',(root->>'sort_order')::integer)
    ON CONFLICT (slug) WHERE slug IS NOT NULL DO NOTHING;
    SELECT id INTO STRICT v_parent_id FROM hocalist.catalogue_categories
      WHERE slug=root->>'slug' AND parent_id IS NULL AND scope=root->>'scope';
    -- Rename only the known original label, never a subsequent admin edit.
    UPDATE hocalist.catalogue_categories c SET label=root->>'label',
      sort_order=(root->>'sort_order')::integer,revision=revision+1,updated_at=now()
      WHERE c.id=v_parent_id AND c.label IN (root->>'legacy_label',root->>'label')
        AND (c.label IS DISTINCT FROM root->>'label' OR c.sort_order<>(root->>'sort_order')::integer);
    FOR leaf IN SELECT value FROM jsonb_array_elements(root->'children') LOOP
      IF (leaf->>'is_root')::boolean THEN v_category_id:=v_parent_id;
      ELSE
        INSERT INTO hocalist.catalogue_categories(parent_id,label,slug,scope,sort_order)
        VALUES(v_parent_id,leaf->>'label',leaf->>'slug',root->>'scope',(leaf->>'sort_order')::integer)
        ON CONFLICT (slug) WHERE slug IS NOT NULL DO NOTHING;
        SELECT c.id INTO STRICT v_category_id FROM hocalist.catalogue_categories c
          WHERE c.slug=leaf->>'slug' AND c.parent_id=v_parent_id AND c.scope=root->>'scope';
      END IF;
      question_order:=0;
      FOR question IN SELECT value FROM jsonb_array_elements(leaf->'questions') LOOP
        SELECT g.id INTO v_group_id FROM hocalist.catalogue_option_groups g
          WHERE g.category_id=v_category_id AND g.label=question->>'label'
          ORDER BY g.created_at,g.id LIMIT 1;
        IF v_group_id IS NULL THEN
          INSERT INTO hocalist.catalogue_option_groups(category_id,label,selection_mode,sort_order)
          VALUES(v_category_id,question->>'label','single',question_order) RETURNING id INTO v_group_id;
        END IF;
        choice_order:=1;
        FOR choice IN SELECT value FROM jsonb_array_elements(question->'options') LOOP
          INSERT INTO hocalist.catalogue_options(group_id,label,sort_order)
          SELECT v_group_id,choice#>>'{}',choice_order WHERE NOT EXISTS(
            SELECT 1 FROM hocalist.catalogue_options o WHERE o.group_id=v_group_id AND o.label=choice#>>'{}');
          choice_order:=choice_order+1;
        END LOOP;
        question_order:=question_order+1;
      END LOOP;
    END LOOP;
  END LOOP;
END
$catalogue$;
COMMIT;
